// Lane coverage: splats generated by gap repair (C3), shown or hidden as one mesh.
//
// scene.json coverage.generated_ply names a PLY in which every splat has generated = 1
// (Muse Image repairs distilled back into splats, modal_jobs/coverage.py --job distil). It is
// loaded as its own SplatMesh in the reconstruction frame, like the background, so the
// "show generated" toggle is a plain visibility flag and needs no per-splat filtering.
import * as THREE from "three";
import { SplatMesh } from "@sparkjsdev/spark";
import type { ViewerContext } from "../context";
import { matrixFromRows, type SceneManifest } from "../scene";

export interface GeneratedSplats {
  /** Whether generated splats are drawn (the toggle state, also before any are loaded). */
  visible(): boolean;
  setVisible(on: boolean): void;
  /** Splats flagged generated in the manifest (0 when there are none). */
  count(): number;
}

export function installGenerated(ctx: ViewerContext, initiallyVisible: boolean): GeneratedSplats {
  const recon = new THREE.Group();
  recon.name = "coverage-generated";
  recon.matrixAutoUpdate = false;
  ctx.scene.add(recon);
  let mesh: SplatMesh | null = null;
  let url: string | null = null;
  let on = initiallyVisible;
  let n = 0;

  const apply = (m: SceneManifest) => {
    const cov = m.coverage;
    n = cov?.generated_splats ?? 0;
    recon.matrix.copy(matrixFromRows(m.world_from_recon));
    recon.matrixWorldNeedsUpdate = true;
    const next = cov?.generated_ply && ctx.sceneBase ? `${ctx.sceneBase}/${cov.generated_ply}` : null;
    if (next === url) return;
    if (mesh) {
      recon.remove(mesh);
      mesh.dispose();
      mesh = null;
    }
    url = next;
    if (!url) return;
    // A rewritten PLY keeps its name; the manifest's count changes with it, so add it to
    // the URL to bypass the browser cache.
    mesh = new SplatMesh({ url: `${url}?n=${n}` });
    mesh.initialized.catch((err: unknown) => console.warn(`[coverage] generated splats: ${String(err)}`));
    mesh.visible = on;
    recon.add(mesh);
    console.info(`[coverage] ${n} generated splats from ${cov?.generated_ply}`);
  };
  ctx.onManifest((m) => apply(m));

  return {
    visible: () => on,
    setVisible(v) {
      on = v;
      if (mesh) mesh.visible = v;
      console.info(`[coverage] generated splats ${v ? "shown" : "hidden"} (${n})`);
    },
    count: () => n,
  };
}
